-- generated by the Capture overlay (Alt+Z) — change hotkeys there
hl.bind("ALT + Z", hl.dsp.exec_cmd("qs ipc call capture toggle"), { desc = "Capture overlay", dont_inhibit = true })
hl.bind("ALT + SHIFT + F10", hl.dsp.exec_cmd("__HOME__/.config/hypr/scripts/capture.sh replay-save"), { desc = "Save instant replay", dont_inhibit = true })
hl.bind("ALT + SHIFT + F9", hl.dsp.exec_cmd("__HOME__/.config/hypr/scripts/capture.sh replay-toggle"), { desc = "Instant replay on/off", dont_inhibit = true })
hl.bind("ALT + F9", hl.dsp.exec_cmd("__HOME__/.config/hypr/scripts/capture.sh record-toggle"), { desc = "Start/stop recording", dont_inhibit = true })
hl.bind("ALT + F1", hl.dsp.exec_cmd("__HOME__/.config/hypr/scripts/screenshot.sh screen"), { desc = "Screenshot of the monitor", dont_inhibit = true })
